package resolvergen

import (
	"errors"
	"path/filepath"
	"strings"
	"unicode"

	"golang.org/x/text/cases"
	"golang.org/x/text/language"

	"github.com/99designs/gqlgen/codegen"
	"github.com/99designs/gqlgen/codegen/templates"
	"github.com/99designs/gqlgen/graphql"
	"github.com/99designs/gqlgen/internal/rewrite"
	"github.com/99designs/gqlgen/plugin"
)

// generatePerObject writes resolvers for layout=follow-object: a file per field of the root
// types (Query, Mutation, Subscription), a file per other object holding its fields, and one
// generated file holding every object's resolver type and its accessor on the root resolver.
//
// Implementations are looked up by method name across the whole package, so resolvers written
// under another layout are found wherever they are and moved to their new file.
func (m *Plugin) generatePerObject(data *codegen.Data) error {
	cfg := data.Config.Resolver

	rewriter, err := rewrite.New(cfg.Dir())
	if err != nil {
		return err
	}

	typesFile := filepath.Join(cfg.Dir(), cfg.TypesFilename)
	files := map[string]*File{}
	fileFor := func(name string) *File {
		key := strings.ToLower(name)
		if files[key] == nil {
			files[key] = &File{name: name}
		}
		return files[key]
	}

	objects := make(codegen.Objects, len(data.Objects)+len(data.Inputs))
	copy(objects, data.Objects)
	copy(objects[len(data.Objects):], data.Inputs)

	for _, o := range objects {
		if o.HasResolvers() {
			caser := cases.Title(language.English, cases.NoLower)
			rewriter.MarkStructCopied(templates.LcFirst(o.Name) + templates.UcFirst(cfg.Type))
			rewriter.GetMethodBody(cfg.Type, caser.String(o.Name))
			types := fileFor(typesFile)
			types.Objects = append(types.Objects, o)
		}

		tmpl := cfg.FieldsFilenameTemplate
		if o.Root {
			tmpl = cfg.OperationsFilenameTemplate
		}
		for _, f := range o.Fields {
			if !f.IsResolver {
				continue
			}
			structName := templates.LcFirst(o.Name) + templates.UcFirst(cfg.Type)
			comment := strings.TrimSpace(
				strings.TrimLeft(rewriter.GetMethodComment(structName, f.GoFieldName), `\`),
			)
			implementation := strings.TrimSpace(rewriter.GetMethodBody(structName, f.GoFieldName))
			resolver := Resolver{
				o,
				f,
				rewriter.GetPrevDecl(structName, f.GoFieldName),
				comment,
				implementation,
				nil,
			}
			var implExists bool
			for _, p := range data.Plugins {
				rImpl, ok := p.(plugin.ResolverImplementer)
				if !ok {
					continue
				}
				if implExists {
					return errors.New("multiple plugins implement ResolverImplementer")
				}
				implExists = true
				resolver.ImplementationRender = rImpl.Implement
			}

			file := fileFor(filepath.Join(cfg.Dir(), objectFilename(tmpl, o.Name, f.Name)))
			file.Resolvers = append(file.Resolvers, &resolver)
			// The implementation may move here from another file, and needs that file's imports.
			file.movedImports = append(
				file.movedImports,
				rewriter.MethodImports(structName, f.GoFieldName)...,
			)
		}
	}

	var allImports []string
	for _, file := range files {
		file.imports = mergeImports(rewriter.ExistingImports(file.name), file.movedImports)
		file.RemainingSource = rewriter.RemainingSource(file.name)

		for _, i := range file.imports {
			allImports = append(allImports, i.ImportPath)
		}
	}
	data.Config.Packages.LoadAllNames(
		allImports...) // Preload all names in one Load call for performance reasons

	newResolverTemplate := resolverTemplate
	if cfg.ResolverTemplate != "" {
		newResolverTemplate = readResolverTemplate(cfg.ResolverTemplate)
	}

	for _, file := range files {
		if fileExists(file.name) && cfg.PreserveResolver {
			// file already exists and config says not to update resolver
			continue
		}
		isTypes := file.name == typesFile
		resolverBuild := &ResolverBuild{
			File:                  file,
			PackageName:           cfg.Package,
			ResolverType:          cfg.Type,
			OmitTemplateComment:   cfg.OmitTemplateComment,
			OmitResolverEmbedding: cfg.OmitResolverEmbedding,
		}

		// The types file holds no implementations, so it gets the standard generated-file header
		// above the package line, which tools use to skip it, instead of the resolver notice.
		var fileNotice strings.Builder
		if !data.Config.OmitGQLGenFileNotice && !isTypes {
			fileNotice.WriteString(`
			// This file will be automatically regenerated based on the schema, any resolver
			// implementations
			// will be copied through when generating and any unknown code will be moved to the end.
			// Code generated by github.com/99designs/gqlgen`,
			)
			if !data.Config.OmitGQLGenVersionInFileNotice {
				fileNotice.WriteString(` version `)
				fileNotice.WriteString(graphql.Version)
			}
		}

		err := templates.Render(templates.Options{
			PackageName:  cfg.Package,
			FileNotice:   fileNotice.String(),
			Filename:     file.name,
			Data:         resolverBuild,
			Packages:     data.Config.Packages,
			Template:     newResolverTemplate,
			PruneOptions: data.Config.GetPruneOptions(),
			// omit_gqlgen_file_notice is for resolver files people edit; this one is always generated.
			GeneratedHeader: isTypes,
		})
		if err != nil {
			return err
		}
	}

	if !fileExists(cfg.Filename) {
		err := templates.Render(templates.Options{
			PackageName: cfg.Package,
			FileNotice: `
				// This file will not be regenerated automatically.
				//
				// It serves as dependency injection for your app, add any dependencies you require
				// here.`,
			Template:     `type {{.}} struct {}`,
			Filename:     cfg.Filename,
			Data:         cfg.Type,
			Packages:     data.Config.Packages,
			PruneOptions: data.Config.GetPruneOptions(),
		})
		if err != nil {
			return err
		}
	}
	return nil
}

// objectFilename fills in a follow-object filename template for a field of an object, such as
// "{field}_{object}.go" for the field createOrder of Mutation: create_order_mutation.go.
func objectFilename(tmpl, objectName, fieldName string) string {
	filename := strings.ReplaceAll(tmpl, "{object}", snakeCase(objectName))
	filename = strings.ReplaceAll(filename, "{field}", snakeCase(fieldName))
	return goSafeFilename(filename)
}

// goSafeFilename keeps a name built from a field or object name from being skipped or misread by
// the go tool: files starting with "_" or "." are ignored, and files ending in "_test.go" are
// only compiled into tests. The schema's "_empty" placeholder field is the common case.
func goSafeFilename(filename string) string {
	dir, name := filepath.Split(filename)
	name = strings.TrimLeft(name, "_.")
	if strings.HasSuffix(name, "_test.go") {
		name = strings.TrimSuffix(name, ".go") + "_.go"
	}
	return dir + name
}

// snakeCase turns a GraphQL name such as "CertificateApplication", "HTTPLog" or "createOrder"
// into "certificate_application", "http_log" or "create_order".
func snakeCase(s string) string {
	runes := []rune(s)
	var sb strings.Builder
	for i, r := range runes {
		if unicode.IsUpper(r) {
			if i > 0 && (unicode.IsLower(runes[i-1]) || unicode.IsDigit(runes[i-1]) ||
				(unicode.IsUpper(runes[i-1]) && i+1 < len(runes) && unicode.IsLower(runes[i+1]))) {
				sb.WriteByte('_')
			}
			r = unicode.ToLower(r)
		}
		sb.WriteRune(r)
	}
	return sb.String()
}

// mergeImports appends the extra imports that the existing ones don't already have.
func mergeImports(existing, extra []rewrite.Import) []rewrite.Import {
	seen := make(map[rewrite.Import]bool, len(existing))
	for _, i := range existing {
		seen[i] = true
	}
	for _, i := range extra {
		if !seen[i] {
			seen[i] = true
			existing = append(existing, i)
		}
	}
	return existing
}
